"""loop/COVERAGE.md: where the loop stands. Never test counts; units, clauses and states."""

from __future__ import annotations

import json
from collections import Counter
from pathlib import Path

from . import graph as G
from . import state as S
from . import units as U
from .plan import Context

REPORT = Path("loop/COVERAGE.md")


def render(ctx: Context, queue: list[dict]) -> str:
    lines = [
        "# SRD rule loop: coverage",
        "",
        "Generated by `python -m scripts.srdloop report`; do not edit.",
        "",
    ]
    scopes = Counter(ctx.scope(u["id"]) for u in ctx.units)
    lines += [
        f"{len(ctx.units)} rule units: {scopes['core']} core, {scopes['content-in']} implemented content, "
        f"{scopes['content-out']} content the engine doesn't implement (not queued until it does).",
        "",
        "## Units by chapter and state",
        "",
        "| Chapter | In scope | " + " | ".join(s for s in S.STATUSES if s != "out-of-scope") + " |",
        "|---|---|" + "---|" * (len(S.STATUSES) - 1),
    ]
    for ch in U.CHAPTER_ORDER:
        ids = [u["id"] for u in ctx.units if u["chapter"] == ch and ctx.scope(u["id"]) != "content-out"]
        if not ids:
            continue
        c = Counter(ctx.state(i)["status"] for i in ids)
        lines.append(
            f"| {ch} | {len(ids)} | "
            + " | ".join(str(c[s]) for s in S.STATUSES if s != "out-of-scope")
            + " |"
        )
    stale = [q["id"] for q in queue if q["stale"]]
    lines += ["", "## Queue", "", f"{len(queue)} units to do ({len(stale)} stale). Next up:", ""]
    lines += [
        f"{i + 1}. `{q['id']}` ({q['scope']}, from stage {q['next_stage']})" for i, q in enumerate(queue[:10])
    ]
    from . import rulings as Ru

    waiting = Ru.pending()
    if waiting:
        how = "`python -m scripts.srdloop ruling accept P-n` or `ruling reject P-n --reason …`"
        lines += ["", "## Rulings awaiting a decision", "", how, ""]
        lines += ["| Id | Unit | Ambiguity | Proposed ruling | Tests |", "|---|---|---|---|---|"]
        lines += [
            f"| {r['id']} | `{r['unit']}` | {r['ambiguity']} | {r['ruling']} | {len(r['tests'])} |"
            for r in waiting
        ]
    doubted = [(uid, n) for uid, st in sorted(ctx.states.items()) for n in st.get("for_review", [])]
    if doubted:
        lines += [
            "",
            "## Tests to review",
            "",
            "The verifier refuted these with low confidence, so they were kept until a person decides:",
            "`python -m scripts.srdloop review keep|remove <test> --reason '…'`.",
            "",
        ]
        lines += ["| Test | Verifier's reason |", "|---|---|"]
        lines += [f"| `{n}` | {_verifier_reason(uid, n)} |" for uid, n in doubted]
    from . import tickets as T

    stuck = [t for t in T.all_tickets() if t["status"] in ("dispute", "stuck")]
    if stuck:
        lines += ["", "## Tickets waiting for a person", ""]
        lines += [f"- {t['id']} ({t['status']}, `{t['unit']}`): {t['title']}" for t in stuck]
    oos = [(uid, x) for uid, st in sorted(ctx.states.items()) for x in st.get("out_of_scope", [])]
    if oos:
        lines += [
            "",
            "## Out of scope",
            "",
            "Clauses the test designer found outside the implemented subset (no ticket).",
            "",
        ]
        lines += ["| Unit | Clause | Reason |", "|---|---|---|"]
        lines += [f"| `{uid}` | {x['clause']} | {x['reason']} |" for uid, x in oos]
    terms = G._glossary_terms(ctx.units)
    unresolved = sorted(
        {
            (u["id"], r)
            for u in ctx.units
            for r in u.get("see_also", [])
            if not G.resolve_see_also(r, ctx.units, terms)
        }
    )
    if unresolved:
        lines += ["", "## Unresolved SRD cross-references", ""]
        lines += [f"- `{uid}`: “{ref}”" for uid, ref in unresolved]
    return "\n".join(lines) + "\n"


def _verifier_reason(uid: str, nodeid: str, runs: Path = Path("loop/runs")) -> str:
    d = runs / uid / "D.json"
    verdicts = json.loads(d.read_text()).get("verdicts", []) if d.exists() else []
    reason = next((v["reason"] for v in verdicts if v["test"] == nodeid), "")
    return " ".join(reason.split()).replace("|", "\\|") or "(none recorded)"


def write(ctx: Context, queue: list[dict], path: Path = REPORT) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render(ctx, queue))
